+        else assert.equal(result.status, "STAGED");
+        assert.equal(f.sink.finish({ failed: true }).status, "DISABLED");
+      } finally {
+        fs.writeSync = originalWrite;
+        fs.openSync = originalOpen;
+        syncBuiltinESMExports();
+      }
